'use client';

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useAuthStore } from '@/store/auth';
import type { User, UserRole } from '@crm/types';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/Button';
import { Modal } from '@/components/ui/Modal';

const ROLE_V: Record<UserRole, 'blue'|'purple'|'green'|'gray'> = { admin:'purple', supervisor:'blue', manager:'green', analyst:'gray' };
const ROLE_L: Record<UserRole, string> = { admin:'Администратор', supervisor:'Руководитель', manager:'Менеджер', analyst:'Аналитик' };
const STATUS_V = { active:'green', inactive:'gray' } as const;
const STATUS_L = { active:'Активный', inactive:'Неактивный' } as const;

export default function UsersPage() {
  const me   = useAuthStore(s => s.user);
  const qc   = useQueryClient();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name:'', login:'', password:'', role:'manager' as UserRole, dept:'', tab:'' });
  const [confirmDel, setConfirmDel] = useState<number|null>(null);

  const allowed = me?.role === 'admin' || me?.role === 'supervisor';
  const canAdmin = me?.role === 'admin';

  const { data: users = [], isLoading } = useQuery<User[]>({
    queryKey: ['users'],
    queryFn:  () => api.get('/users'),
    enabled: !!allowed,
  });

  const create = useMutation({
    mutationFn: (body: typeof form) => api.post('/users', body),
    onSuccess: () => { qc.invalidateQueries({ queryKey:['users'] }); setOpen(false); },
  });

  const del = useMutation({
    mutationFn: (id: number) => api.delete(`/users/${id}`),
    onSuccess: () => { qc.invalidateQueries({ queryKey:['users'] }); setConfirmDel(null); },
  });

  if (!allowed) {
    return (
      <div className="flex flex-col items-center justify-center py-24 text-center">
        <div className="text-5xl mb-4">🔒</div>
        <h2 className="text-xl font-bold mb-2">Недостаточно прав</h2>
        <p className="text-gray-400 text-sm">Управление пользователями доступно только администраторам и руководителям</p>
      </div>
    );
  }

  if (isLoading) return <div className="flex items-center justify-center h-64 text-gray-400 text-sm">Загрузка...</div>;

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <div>
          <h2 className="text-2xl font-extrabold tracking-tight">Пользователи</h2>
          <p className="text-sm text-gray-400 mt-0.5">{users.length} сотрудников в системе</p>
        </div>
        {canAdmin && <Button onClick={() => setOpen(true)}>+ Пользователь</Button>}
      </div>

      <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {['Сотрудник','Логин','Роль','Отдел','Таб. №','Клиентов','Статус','Последний вход',canAdmin?'':''].map((h,i) => (
                  <th key={i} className="text-left px-4 py-2.5 text-[11px] font-semibold uppercase tracking-wider text-gray-400">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {users.map(u => (
                <tr key={u.id} className="border-b border-gray-100 last:border-0 hover:bg-gray-50 transition-colors">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      <div className="w-8 h-8 rounded-full bg-brand-700 text-white text-xs font-bold flex items-center justify-center flex-shrink-0">
                        {u.initials}
                      </div>
                      <div className="text-sm font-semibold">{u.name}</div>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-sm font-mono text-gray-500">{u.login}</td>
                  <td className="px-4 py-3"><Badge variant={ROLE_V[u.role]}>{ROLE_L[u.role]}</Badge></td>
                  <td className="px-4 py-3 text-sm text-gray-600">{u.dept || '—'}</td>
                  <td className="px-4 py-3 text-sm text-gray-500">{u.tab || '—'}</td>
                  <td className="px-4 py-3 text-sm font-medium">{u.clients_count ?? 0}</td>
                  <td className="px-4 py-3"><Badge variant={STATUS_V[u.status]}>{STATUS_L[u.status]}</Badge></td>
                  <td className="px-4 py-3 text-xs text-gray-400">{u.last_login || '—'}</td>
                  {canAdmin && (
                    <td className="px-4 py-3">
                      {u.id !== me?.id && (
                        <button onClick={() => setConfirmDel(u.id)} className="text-xs text-red-400 hover:text-red-600 transition-colors">Удалить</button>
                      )}
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Create modal */}
      <Modal open={open} title="Новый пользователь" onClose={() => setOpen(false)}
        footer={<>
          <Button variant="ghost" onClick={() => setOpen(false)}>Отмена</Button>
          <Button onClick={() => create.mutate(form)} disabled={!form.name || !form.login || !form.password || create.isPending}>Создать</Button>
        </>}>
        <div className="space-y-3">
          <div><label className="field-label">Полное имя *</label><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="form-input" placeholder="Имя Фамилия Отчество"/></div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="field-label">Логин *</label><input value={form.login} onChange={e=>setForm({...form,login:e.target.value})} className="form-input" placeholder="a.ivanov"/></div>
            <div><label className="field-label">Пароль *</label><input type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} className="form-input"/></div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="field-label">Роль</label>
              <select value={form.role} onChange={e=>setForm({...form,role:e.target.value as UserRole})} className="form-input">
                <option value="manager">Менеджер</option><option value="supervisor">Руководитель</option><option value="analyst">Аналитик</option><option value="admin">Администратор</option>
              </select>
            </div>
            <div><label className="field-label">Отдел</label><input value={form.dept} onChange={e=>setForm({...form,dept:e.target.value})} className="form-input" placeholder="Корпоративный блок"/></div>
          </div>
          <div><label className="field-label">Таб. номер</label><input value={form.tab} onChange={e=>setForm({...form,tab:e.target.value})} className="form-input" placeholder="ИБ-001"/></div>
        </div>
      </Modal>

      {/* Delete confirm modal */}
      <Modal open={confirmDel !== null} title="Удалить пользователя?" onClose={() => setConfirmDel(null)}
        footer={<>
          <Button variant="ghost" onClick={() => setConfirmDel(null)}>Отмена</Button>
          <Button variant="danger" onClick={() => confirmDel && del.mutate(confirmDel)} disabled={del.isPending}>Удалить</Button>
        </>}>
        <p className="text-sm text-gray-600">Это действие необратимо. Все данные пользователя будут удалены.</p>
      </Modal>
    </div>
  );
}
